"function createSim(opts = {}) {
  const { airMode = "polyline", clampLeakHp = false, menderGroundOnly = false } = opts;

  const GROUND_TILES = [[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]];
  const AIR_TILES = airMode === "polyline"
    ? [[0,6],[21,6],[21,11],[23,11]]
    : [[0,6],[21,6],[21,11]]; // just in case

  function buildRoute(tiles) {
    const pts = tiles.map(([tx, ty]) => [100 * tx + 50, 100 * ty + 50]);
    const segs = [];
    let total = 0;
    for (let i = 0; i < pts.length - 1; i++) {
      const [x0, y0] = pts[i];
      const [x1, y1] = pts[i + 1];
      const dx = x1 - x0;
      const dy = y1 - y0;
      const len = Math.abs(dx) + Math.abs(dy);
      segs.push({ x0, y0, sx: Math.sign(dx), sy: Math.sign(dy), start: total, len });
      total += len;
    }
    return { pts, segs, length: opts.forceAir2600 && tiles === AIR_TILES ? 2600 : total };
  }

  function posAt(route, progress) {
    if (progress <= 0) return [route.pts[0][0], route.pts[0][1]];
    for (let i = 0; i < route.segs.length; i++) {
      const s = route.segs[i];
      if (progress <= s.start + s.len || i === route.segs.length - 1) {
        const d = Math.min(s.len, progress - s.start);
        return [s.x0 + s.sx * d, s.y0 + s.sy * d];
      }
    }
    const last = route.pts[route.pts.length - 1];
    return [last[0], last[1]];
  }

